import heapq

class Graph:
    def __init__(self, edges, directed=False):
        self.adj_matrix = self._initialize_matrix(edges)
        self.directed = directed
        self.num_nodes = len(edges)

    def _initialize_matrix(self, edges):
        num_nodes = len(edges)
        adj_matrix = [[float('inf')] * num_nodes for _ in range(num_nodes)]
        for i, edge in enumerate(edges):
            if edge is not None:
                adj_matrix[i][edge[0]] = edge[1]
                if not self.directed:
                    adj_matrix[edge[0]][i] = edge[1]
        return adj_matrix

    def get_neighbors(self, node):
        return self.adj_matrix[node]

    def is_connected(self, node1, node2):
        return self.adj_matrix[node1][node2] != float('inf')

    def get_num_nodes(self):
        return self.num_nodes
