def dijkstra(graph, start_node):
    num_nodes = graph.get_num_nodes()
    distances = {node: float('inf') for node in range(num_nodes)}
    distances[start_node] = 0
    previous_nodes = {node: None for node in range(num_nodes)}

    pq = [(0, start_node)]
    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in enumerate(graph.get_neighbors(current_node)):
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    return distances, previous_nodes

def shortest_path(graph, start_node, end_node):
    _, previous_nodes = dijkstra(graph, start_node)
    path = []
    while end_node is not None:
        path.insert(0, end_node)
        end_node = previous_nodes[end_node]
    return path

