### Depth-First Search (DFS) Implementation

```python
class Graph:
    def __init__(self, graph_dict=None):
        if graph_dict is None:
            graph_dict = {}
        self._graph_dict = graph_dict

    def get_neighbors(self, vertex):
        return self._graph_dict[vertex]

    def dfs(self, start, goal, visited=None, path=None):
        if visited is None:
            visited = set()
        if path is None:
            path = [start]

        if start == goal:
            return path

        visited.add(start)

        for next_node in self.get_neighbors(start):
            if next_node not in visited:
                new_path = self.dfs(next_node, goal, visited, path + [next_node])
                if new_path:
                    return new_path

        return None

